import html
script=DATA.pop('__contact_script__')
if 'id="masker-aanvraag"' not in ct: ct=ct.replace('</body>',script+'</body>')
DATA['contact.html']=ct
stamp=datetime.datetime.now().strftime('%Y%m%d-%H%M%S')
backup=root/'backups'/('maskers-'+stamp)
for name,content in DATA.items():
    target=root/name
    if target.exists():
        old=backup/name
        old.parent.mkdir(parents=True,exist_ok=True)
        old.write_bytes(target.read_bytes())
    target.parent.mkdir(parents=True,exist_ok=True)
    if name.endswith('.webp'): target.write_bytes(base64.b64decode(content))
